structureCode.vanilla:
import { createToggleGroup } from '@/components/ui/toggle-group';

// Seleção única (single). O nome do grupo e o de cada item só de ícone são
// obrigatórios, e viajam com o grupo e com o item.
const grupo = createToggleGroup({
  type: 'single',
  'aria-label': 'Alinhamento do texto',
  items: [
    { value: 'left',   'aria-label': 'Alinhar à esquerda' },
    { value: 'center', 'aria-label': 'Centralizar' },
    { value: 'right',  'aria-label': 'Alinhar à direita' },
  ],
  defaultValue: 'left',
  onValueChange: (valor) => aplicar(valor),
});

extensibilityCode.react:
// ToggleGroup type=multiple com analytics
const [formats, setFormats] = useState<string[]>([]);

<ToggleGroup
  type="multiple"
  value={formats}
  onValueChange={(next) => {
    track('field_change', {
      component: 'toggle_group',
      field_name: 'text_formatting',
      value: next.join(','),
    });
    setFormats(next);
  }}
  aria-label="Formatação"
>
  <ToggleGroupItem value="bold" aria-label="Negrito">
    <Bold aria-hidden="true" />
  </ToggleGroupItem>
  <ToggleGroupItem value="italic" aria-label="Itálico">
    <Italic aria-hidden="true" />
  </ToggleGroupItem>
  <ToggleGroupItem value="underline" aria-label="Sublinhado">
    <Underline aria-hidden="true" />
  </ToggleGroupItem>
</ToggleGroup>

